/** A ledger of accounts and the balanced entries posted against them. */
export class Ledger {
  #accounts = new Map();

  #entries = new Map();

  #order = [];

  /**
   * Resolve the cut-off shared by the reporting methods.
   *
   * @param {{asOf?: number}} options Reporting options.
   * @returns {number} Inclusive cut-off.
   */
  #asOf(options) {
    const { asOf = Infinity } = options ?? {};
    if (asOf === Infinity) return asOf;
    return checkTime(asOf, 'asOf');
  }

  /**
   * Look up an account or fail.
   *
   * @param {string} accountId Account id.
   * @returns {Readonly<object>} The account.
   */
  #requireAccount(accountId) {
    const account = this.#accounts.get(accountId);
    if (!account) throw new LedgerError('UNKNOWN_ACCOUNT', `unknown account: ${accountId}`);
    return account;
  }

  /**
   * Store an already-validated entry.
   *
   * @param {object} draft Entry fields.
   * @returns {Readonly<object>} The stored entry.
   */
  #store(draft) {
    const entry = Object.freeze({
      id: draft.id,
      at: draft.at,
      seq: this.#order.length + 1,
      memo: draft.memo,
      lines: Object.freeze(draft.lines.map((line) => Object.freeze({ account: line.account, amountCents: line.amountCents }))),
      reverses: draft.reverses ?? null,
      reversedBy: null,
    });
    this.#entries.set(entry.id, entry);
    this.#order.push(entry);
    return entry;
  }

  /**
   * Replace a stored entry with an updated copy, preserving its position.
   *
   * @param {Readonly<object>} entry Entry to replace.
   * @param {object} patch Fields to override.
   * @returns {Readonly<object>} The replacement.
   */
  #replace(entry, patch) {
    const updated = Object.freeze({ ...entry, ...patch });
    this.#entries.set(updated.id, updated);
    this.#order[updated.seq - 1] = updated;
    return updated;
  }
"}

